namespace ghidra.feature.vt.gui.actions;

using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.provider.functionassociation;
using docking;
using docking.action;

/**
 * An abstract action that can be extended for each of the actions that create a manual match
 * plus possibly making some follow on changes related to that match.
 * This class provides default action enablement based on context.
 */
abstract class AbstractCreateManualMatchAction : DockingAction {

	protected static readonly string MENU_GROUP = "Create";

	protected VTController controller;

	/**
	 * Constructor.
	 * @param name the action's name
	 * @param owner the action's owner
	 * @param controller the controller for the version tracking session
	 */
	AbstractCreateManualMatchAction(string name, string owner, VTController controller) : base(name, owner)
    {
		this.controller = controller;
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is FunctionAssociationContext)) {
			return false;
		}

		FunctionAssociationContext providerContext = (FunctionAssociationContext) context;
		return providerContext.canCreateMatch();
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		return (context is FunctionAssociationContext);
	}
}
